0: //! Trait providing a unified test/benchmark interface across all Any database variants.
1: 
2: use crate::{
3:     merkle::{Family, Location, Proof},
4:     qmdb::{Error, operation::Key},
5: };
6: use commonware_codec::CodecShared;
7: use commonware_cryptography::Digest;
8: use commonware_runtime::Handle;
9: use core::num::NonZeroU64;
10: use std::{future::Future, ops::Range};
