12: /// Unmerkleized batch of operations.
13: pub trait UnmerkleizedBatch<Db: ?Sized>: Sized {
14:     type Family: Family;
15:     type K;
16:     type V;
17:     type Metadata;
18:     type Merkleized: MerkleizedBatch;
19: 
20:     /// Record a mutation. Use `Some(value)` for update/create, `None` for delete.
21:     fn write(self, key: Self::K, value: Option<Self::V>) -> Self;
22: 
23:     /// Resolve mutations, compute the new root, and return a merkleized batch.
24:     fn merkleize(
25:         self,
26:         db: &Db,
27:         metadata: Option<Self::Metadata>,
28:     ) -> impl Future<Output = Result<Self::Merkleized, Error<Self::Family>>>;
29: }
30: 
31: /// Merkleized batch of operations.
32: pub trait MerkleizedBatch: Sized {
33:     type Digest: Digest;
34: 
35:     /// Return the committed root.
36:     fn root(&self) -> Self::Digest;
37: }
38: 
39: /// The result of applying a batch: the database and the range of written operations.
40: pub type ApplyBatchResult<D> =
41:     Result<(D, Range<Location<<D as BatchableDb>::Family>>), Error<<D as BatchableDb>::Family>>;
42: 
43: /// Db that supports updates through a batch API.
44: pub trait BatchableDb: Sized {
45:     type Family: Family;
46:     type K;
47:     type V;
48:     type Merkleized: MerkleizedBatch;
49:     type Batch: UnmerkleizedBatch<
50:             Self,
51:             Family = Self::Family,
52:             K = Self::K,
53:             V = Self::V,
54:             Metadata = Self::V,
55:             Merkleized = Self::Merkleized,
56:         >;
57: 
58:     /// Create a new speculative batch of operations with this database as its parent.
59:     fn new_batch(&self) -> Self::Batch;
60: 
61:     /// Apply a merkleized batch, returning the range of written operations.
62:     fn apply_batch(self, batch: Self::Merkleized) -> impl Future<Output = ApplyBatchResult<Self>>;
63: }
