177: /// Implements [`DbAny`] by delegating each method to an identically-named inherent method.
178: ///
179: /// # Syntax
180: ///
181: /// ```ignore
182: /// impl_db_any! {
183: ///     [$($generics)*] TypeName
184: ///     where { $where_clause }
185: ///     Family = .., Key = .., Value = .., Digest = ..
186: /// }
187: /// ```
188: macro_rules! impl_db_any {
189:     (
190:         [$($gen:tt)*] $ty:ty
191:         where { $($where_clause:tt)* }
192:         Family = $fam:ty, Key = $key:ty, Value = $val:ty, Digest = $dig:ty
193:     ) => {
194:         impl<$($gen)*> $crate::qmdb::any::traits::DbAny<$fam> for $ty
195:         where $($where_clause)*
196:         {
197:             type Key = $key;
198:             type Value = $val;
199:             type Digest = $dig;
200: 
201:             async fn get(&self, key: &$key) -> ::core::result::Result<Option<$val>, $crate::qmdb::Error<$fam>> {
202:                 <$ty>::get(self, key).await
203:             }
204: 
205:             async fn get_many(&self, keys: &[&$key]) -> ::core::result::Result<Vec<Option<$val>>, $crate::qmdb::Error<$fam>> {
206:                 <$ty>::get_many(self, keys).await
207:             }
208: 
209:             fn root(&self) -> $dig {
210:                 <$ty>::root(self)
211:             }
212: 
213:             fn bounds(&self) -> ::std::ops::Range<$crate::merkle::Location<$fam>> {
214:                 <$ty>::bounds(self)
215:             }
216: 
217:             async fn get_metadata(
218:                 &self,
219:             ) -> ::core::result::Result<Option<$val>, $crate::qmdb::Error<$fam>> {
220:                 <$ty>::get_metadata(self).await
221:             }
222: 
223:             async fn prune(
224:                 self,
225:                 loc: $crate::merkle::Location<$fam>,
226:             ) -> ::core::result::Result<Self, $crate::qmdb::Error<$fam>> {
227:                 <$ty>::prune(self, loc).await
228:             }
229: 
230:             async fn start_sync(
231:                 self,
232:             ) -> ::core::result::Result<
233:                 (Self, ::commonware_runtime::Handle<()>),
234:                 $crate::qmdb::Error<$fam>,
235:             > {
236:                 <$ty>::start_sync(self).await
237:             }
238: 
239:             async fn commit(self) -> ::core::result::Result<Self, $crate::qmdb::Error<$fam>> {
240:                 <$ty>::commit(self).await
241:             }
242: 
243:             async fn sync(self) -> ::core::result::Result<Self, $crate::qmdb::Error<$fam>> {
244:                 <$ty>::sync(self).await
245:             }
246: 
247:             async fn destroy(self) -> ::core::result::Result<(), $crate::qmdb::Error<$fam>> {
248:                 <$ty>::destroy(self).await
249:             }
250: 
251:             fn inactivity_floor_loc(&self) -> $crate::merkle::Location<$fam> {
252:                 <$ty>::inactivity_floor_loc(self)
253:             }
254: 
255:             fn sync_boundary(&self) -> $crate::merkle::Location<$fam> {
256:                 <$ty>::sync_boundary(self)
257:             }
258:         }
259:     };
260: }
261: 
262: pub(crate) use impl_db_any;
263: 
264: /// Implements [`Provable`] by delegating each method to an identically-named inherent method.
265: macro_rules! impl_provable {
266:     (
267:         [$($gen:tt)*] $ty:ty
268:         where { $($where_clause:tt)* }
269:         Family = $fam:ty, Operation = $op:ty
270:     ) => {
271:         impl<$($gen)*> $crate::qmdb::any::traits::Provable<$fam> for $ty
272:         where $($where_clause)*
273:         {
274:             type Operation = $op;
275: 
276:             async fn historical_proof(
277:                 &self,
278:                 historical_size: $crate::merkle::Location<$fam>,
279:                 start_loc: $crate::merkle::Location<$fam>,
280:                 max_ops: ::core::num::NonZeroU64,
281:             ) -> ::core::result::Result<
282:                 ($crate::merkle::Proof<$fam, <Self as $crate::qmdb::any::traits::DbAny<$fam>>::Digest>, Vec<$op>),
283:                 $crate::qmdb::Error<$fam>,
284:             > {
285:                 <$ty>::historical_proof(self, historical_size, start_loc, max_ops)
286:                     .await
287:             }
288:         }
289:     };
290: }
291: 
292: pub(crate) use impl_provable;
